 const EmailCopiesPage({super.key});
 @override Widget build(BuildContext context,WidgetRef ref)=>Scaffold(appBar:AppBar(title:const Text('Retained private email copies')),body:ref.watch(integrationCopiesProvider).when(loading:integrationLoading,error:(e,_)=>integrationError(e),data:(rows)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Latest 100 captured copies. Disabling capture does not delete them. Removal deletes the active copy and attempts to remove its own input file; it cannot securely erase SQLite free pages, OS caches, backups or previously shared/external copies.'),if(rows.isEmpty)const Text('No retained email copies.'),...rows.map((r)=>Card(child:Column(children:[ListTile(title:Text(r['title'] as String),subtitle:Text('Device capture time (not email date): ${DateTime.fromMillisecondsSinceEpoch((r['captured_ts'] as num).toInt()*1000,isUtc:true).toIso8601String()}')),TextButton(onPressed:()=>context.push('/reader/${r['id']}'),child:const Text('Open private copy')),TextButton(onPressed:()async{if(!await integrationConfirm(context,'Delete this retained email copy?','Other originals are untouched. Attached annotations, claim reviews and source links are removed; decisions, subscriptions and existing summary contents remain and are not canceled. Shared/external copies and backups cannot be retracted. This is active-library removal, not secure erasure.')){return;}try{final repo=await ref.read(bootstrapProvider.future);final result=repo.integrations('email_delete',r['id']) as Map<String,dynamic>;ref.invalidate(integrationCopiesProvider);ref.invalidate(itemsProvider);ref.invalidate(dailySignalProvider);ref.invalidate(consumerDocumentsProvider);ref.invalidate(consumerDocumentProvider);ref.invalidate(integrationCalendarProvider);ref.invalidate(topicsProvider);ref.invalidate(entitiesProvider);ref.invalidate(memoryTimelineProvider);ref.invalidate(relationshipsProvider);if(context.mounted){integrationSnack(context,result['warning'] as String);}}catch(e){if(context.mounted){integrationSnack(context,'$e');}}},child:const Text('Delete retained email copy'))])))])));
